import{_ as s,W as l,s as a,u as p,I as t,ah as r,w as o,Z as n,A as d}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const T=JSON.parse('{"title":"如何在 nginx 中缓存静态文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 nginx 中缓存静态文件 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 nginx 中缓存静态文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 nginx 中缓存静态文件 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160808 How to cache static files on nginx","title":"如何在 nginx 中缓存静态文件","tag":"201608"},"relativePath":"201608/20160808 How to cache static files on nginx.md","filePath":"[post].md"}'),g={name:"201608/20160808 How to cache static files on nginx.md"};function x(u,e,m,f,c,C){const i=l("Link");return p(),a("div",null,[e[33]||(e[33]=t("h1",{id:"如何在-nginx-中缓存静态文件",tabindex:"-1"},[o("如何在 nginx 中缓存静态文件 "),t("a",{class:"header-anchor",href:"#如何在-nginx-中缓存静态文件","aria-label":"Permalink to 如何在 nginx 中缓存静态文件"},"​")],-1)),e[34]||(e[34]=t("p",null,"这篇教程说明你应该怎样配置 nginx、设置 HTTP 头部过期时间，用 Cache-Control 中的 max-age 标记为静态文件（比如图片、 CSS 和 Javascript 文件）设置一个时间，这样用户的浏览器就会缓存这些文件。这样能节省带宽，并且在访问你的网站时会显得更快些（如果用户第二次访问你的网站，将会使用浏览器缓存中的静态文件）。",-1)),e[35]||(e[35]=t("h3",{id:"_1、准备事项",tabindex:"-1"},[o("1、准备事项 "),t("a",{class:"header-anchor",href:"#_1、准备事项","aria-label":"Permalink to 1、准备事项"},"​")],-1)),t("p",null,[e[1]||(e[1]=o("我想你需要一个正常工作的 nginx 软件，就像这篇教程里展示的：")),n(i,{href:"1"},{default:d(()=>e[0]||(e[0]=[o("在 Ubuntu 16.04 LTS 上安装 Nginx，PHP 7 和 MySQL 5.7 (LEMP)")])),_:1}),e[2]||(e[2]=o("。"))]),e[36]||(e[36]=t("h3",{id:"_2-配置-nginx",tabindex:"-1"},[o("2 配置 nginx "),t("a",{class:"header-anchor",href:"#_2-配置-nginx","aria-label":"Permalink to 2 配置 nginx"},"​")],-1)),t("p",null,[e[4]||(e[4]=o("可以参考 ")),n(i,{href:"2"},{default:d(()=>e[3]||(e[3]=[o("expires")])),_:1}),e[5]||(e[5]=o(" 指令手册来设置 HTTP 头部过期时间，这个标记可以放在 ")),e[6]||(e[6]=t("code",null,"http {}",-1)),e[7]||(e[7]=o("、")),e[8]||(e[8]=t("code",null,"server {}",-1)),e[9]||(e[9]=o("、")),e[10]||(e[10]=t("code",null,"location {}",-1)),e[11]||(e[11]=o(" 等语句块或者 ")),e[12]||(e[12]=t("code",null,"location {}",-1)),e[13]||(e[13]=o(" 语句块中的条件语句中。一般会在 ")),e[14]||(e[14]=t("code",null,"location",-1)),e[15]||(e[15]=o(" 语句块中用 ")),e[16]||(e[16]=t("code",null,"expires",-1)),e[17]||(e[17]=o(" 指令控制你的静态文件，就像下面一样："))]),e[37]||(e[37]=r(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ~*  \\.(jpg|jpeg|png|gif|ico|css|js)$ {</span></span>
<span class="line"><span>   expires 365d;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的例子中，所有后缀名是 <code>.jpg</code>、 <code>.jpeg</code>、 <code>.png</code>、 <code>.gif</code>、 <code>.ico</code>、 <code>.css</code> 和 <code>.js</code> 的文件会在浏览器访问该文件之后的 365 天后过期。因此你要确保 <code>location {}</code> 语句块仅仅包含能被浏览器缓存的静态文件。</p><p>然后重启 nginx 进程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/etc/init.d/nginx reload</span></span></code></pre></div><p>你可以在 <code>expires</code> 指令中使用以下的时间设置：</p><ul><li><code>off</code> 让 <code>Expires</code> 和 <code>Cache-Control</code> 头部不能被更改。</li><li><code>epoch</code> 将 <code>Expires</code> 头部设置成 1970 年 1 月 1 日 00:00:01。</li><li><code>max</code> 设置 <code>Expires</code> 头部为 2037 年 12 月 31 日 23:59:59，设置 <code>Cache-Control</code> 的最大存活时间为 10 年</li><li>没有 <code>@</code> 前缀的时间意味着这是一个与浏览器访问时间有关的过期时间。可以指定一个负值的时间，就会把 Cache-Control 头部设置成 no-cache。例如：<code>expires 10d</code> 或者 <code>expires 14w3d</code>。</li><li>有 <code>@</code> 前缀的时间指定在一天中的某个时间过期，格式是 Hh 或者 Hh:Mm，H 的范围是 0 到 24，M 的范围是 0 到 59，例如：<code>expires @15:34</code>。</li></ul><p>你可以用以下的时间单位：</p><ul><li><code>ms</code>: 毫秒</li><li><code>s</code>: 秒</li><li><code>m</code>: 分钟</li><li><code>h</code>: 小时</li><li><code>d</code>: 天</li><li><code>w</code>: 星期</li><li><code>M</code>: 月 (30 天)</li><li><code>y</code>: 年 (365 天)</li></ul><p>例如：<code>1h30m</code> 表示一小时三十分钟，<code>1y6m</code> 表示一年六个月。</p><p>注意，要是你用一个在将来很久才会过期的头部，当组件修改时你就要改变组件的文件名。因此给文件指定版本是一个不错的方法。例如，如果你有个 javascript.js 文件 并且你要修改它，你可以在修改的文件名字后面添加一个版本号。这样浏览器就要下载这个文件，如果你没有更改文件名，浏览器将从缓存里面加载（旧的）文件。</p><p>除了把基于浏览器访问时间设置 <code>Expires</code> 头部（比如 <code>expires 10d</code>）之外，也可以通过在时间前面的 <code>modified</code> 关键字，将 <code>Expires</code> 头部的基准设为文件修改的时间（请注意这仅仅对存储在硬盘的实际文件有效）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expires modified 10d;</span></span></code></pre></div><h3 id="_3-测试" tabindex="-1">3 测试 <a class="header-anchor" href="#_3-测试" aria-label="Permalink to 3 测试">​</a></h3><p>要测试你的配置是否有效，可以用火狐浏览器的开发者工具中的网络分析功能，然后用火狐访问一个静态文件（比如一张图片）。在输出的头部信息里，应该能看到 <code>Expires</code> 头部和有 <code>max-age</code> 标记的 <code>Cache-Control</code> 头部（<code>max-age</code> 标记包含了一个以秒为单位的值，比如 31536000 就是指今后的一年）</p><p><img src="https://www.howtoforge.com/images/how-to-cache-static-files-on-nginx/accept_headers.png" alt=""></p><h3 id="_4-链接" tabindex="-1">4 链接 <a class="header-anchor" href="#_4-链接" aria-label="Permalink to 4 链接">​</a></h3>`,16)),t("p",null,[e[19]||(e[19]=o("nginx 的 Http 头部模块（HttpHeadersModule）: ")),n(i,{href:"http://wiki.nginx.org/HttpHeadersModule"},{default:d(()=>e[18]||(e[18]=[o("http://wiki.nginx.org/HttpHeadersModule")])),_:1})]),e[38]||(e[38]=t("hr",null,null,-1)),t("p",null,[e[21]||(e[21]=o("via: ")),n(i,{href:"https://www.howtoforge.com/tutorial/how-to-cache-static-files-on-nginx/"},{default:d(()=>e[20]||(e[20]=[o("https://www.howtoforge.com/tutorial/how-to-cache-static-files-on-nginx/")])),_:1})]),t("p",null,[e[25]||(e[25]=o("作者：")),n(i,{href:"https://www.howtoforge.com/tutorial/how-to-cache-static-files-on-nginx/"},{default:d(()=>e[22]||(e[22]=[o("Falko Timme")])),_:1}),e[26]||(e[26]=o(" 译者：")),n(i,{href:"https://github.com/GitFuture"},{default:d(()=>e[23]||(e[23]=[o("GitFuture")])),_:1}),e[27]||(e[27]=o(" 校对：")),n(i,{href:"https://github.com/wxy"},{default:d(()=>e[24]||(e[24]=[o("wxy")])),_:1})]),t("p",null,[e[30]||(e[30]=o("本文由 ")),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>e[28]||(e[28]=[o("LCTT")])),_:1}),e[31]||(e[31]=o(" 原创编译，")),n(i,{href:"https://linux.cn/"},{default:d(()=>e[29]||(e[29]=[o("Linux中国")])),_:1}),e[32]||(e[32]=o(" 荣誉推出"))])])}const h=s(g,[["render",x]]);export{T as __pageData,h as default};
